-- Migration 026: expanded checkpoint explanations and try-it solutions for SMB lessons.
-- Auto-generated by json_encode_lesson_explanations_v2.dart.
-- Surgically patches skills.lesson JSONB without re-emitting the full lesson.
BEGIN;

CREATE OR REPLACE FUNCTION public._patch_cp_smb(
    p_skill_code TEXT,
    p_stem_fr TEXT,
    p_new_explanation TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_question_idx INT;
    v_block JSONB;
    v_questions JSONB;
    v_question JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
    v_n_questions INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'checkpoint' THEN CONTINUE; END IF;
            v_questions := v_block->'questions';
            IF v_questions IS NULL THEN CONTINUE; END IF;
            v_n_questions := jsonb_array_length(v_questions);
            FOR v_question_idx IN 0..(v_n_questions - 1) LOOP
                v_question := v_questions->v_question_idx;
                IF v_question->>'stem_fr' = p_stem_fr THEN
                    v_lesson := jsonb_set(
                        v_lesson,
                        ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'questions', v_question_idx::text, 'explanation_fr'],
                        to_jsonb(p_new_explanation)
                    );
                    v_found := TRUE;
                END IF;
            END LOOP;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public._patch_tryit_smb(
    p_skill_code TEXT,
    p_problem_fr TEXT,
    p_new_hint TEXT,
    p_new_solution TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_block JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'try_it' THEN CONTINUE; END IF;
            IF v_block->>'problem_fr' = p_problem_fr THEN
                v_lesson := jsonb_set(
                    v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'hint_fr'],
                    to_jsonb(p_new_hint)
                );
                v_lesson := jsonb_set(
                    v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'solution_fr'],
                    to_jsonb(p_new_solution)
                );
                v_found := TRUE;
            END IF;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

SELECT public._patch_tryit_smb('arithmetic_seq', 'Calcule $2 + 5 + 8 + \dots + 50$ (raison 3, partant de 2).', 'On a une suite arithmétique de premier terme 2 et raison 3. La somme $u_p + u_{p+1} + \dots + u_n$ vaut (nombre de termes) × (premier + dernier) / 2. Première étape : trouver combien de termes la somme contient. Le terme général est $u_n = 2 + 3n$ (avec $u_0 = 2$). Trouve le rang $n$ tel que $u_n = 50$, ajoute 1 pour le nombre de termes, puis applique la formule.', 'On reconnaît la somme d''une suite arithmétique de premier terme $u_0 = 2$ et de raison $r = 3$. Le terme général est $u_n = u_0 + n r = 2 + 3n$. On cherche $n$ tel que $u_n = 50$ : $2 + 3n = 50$, donc $3n = 48$, donc $n = 16$. **Attention** : le rang 16 correspond au 17ème terme (les rangs commencent à 0). On a donc 17 termes en tout. La formule de Gauss donne $S = (\text{nb termes}) \times \dfrac{\text{premier} + \text{dernier}}{2} = 17 \times \dfrac{2 + 50}{2} = 17 \times 26 = 442$.');
SELECT public._patch_tryit_smb('limit_calc', 'Calcule $\lim_{x\to 1} \dfrac{x^2 - 1}{x - 1}$.', 'Substitution directe : $1^2 - 1 = 0$ et $1 - 1 = 0$, forme indéterminée $0/0$. **Cette forme appelle une factorisation cachée** — numérateur et dénominateur ont une racine commune en $x = 1$. Pense à l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$.', 'En $x = 1$ : numérateur $1 - 1 = 0$, dénominateur $1 - 1 = 0$, forme **$0/0$**. On factorise via l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$ : $x^2 - 1 = (x-1)(x+1)$. La fraction se réécrit $\dfrac{(x-1)(x+1)}{x-1}$. Le facteur $(x-1)$ se simplifie (légitime car $x \ne 1$ dans la limite). Il reste $\lim_{x\to 1}(x+1) = 1 + 1 = 2$. **Pattern à retenir** : forme $0/0 \Rightarrow$ chercher une factorisation cachée. Le résultat 2 est aussi la dérivée de $x^2$ en 1.');
SELECT public._patch_tryit_smb('tvi', 'Montre que $\cos(x) = x$ admet une solution dans $[0, \pi/2]$.', 'Astuce classique : ramène à la forme $g(x) = 0$ en posant $g(x) = \cos(x) - x$. Vérifie ensuite que $g$ est continue et change de signe entre les bornes pour appliquer le TVI.', 'On pose $g(x) = \cos(x) - x$ ; les solutions de $\cos(x) = x$ sont les zéros de $g$. **Étape 1 — Continuité** : $g$ est continue sur $[0, \pi/2]$ comme différence de fonctions continues. **Étape 2 — Évaluation aux bornes** : $g(0) = 1 - 0 = 1 > 0$. $g(\pi/2) = 0 - \pi/2 \approx -1{,}57 < 0$. **Étape 3 — TVI** : 0 est compris entre $g(\pi/2)$ et $g(0)$, donc il existe $c \in ]0, \pi/2[$ tel que $g(c) = 0$, c''est-à-dire $\cos(c) = c$. Numériquement, $c \approx 0{,}739$.');
SELECT public._patch_tryit_smb('integral_apps', 'Calcule l''aire entre la courbe $y = x^2$ et l''axe Ox sur $[0, 2]$.', 'L''aire est l''intégrale définie de $f(x) = x^2$ entre 0 et 2. Trouve d''abord une primitive de $x^2$, puis applique Newton-Leibniz.', 'L''aire cherchée est $A = \int_0^2 x^2\,dx$. **Primitive** : $\int x^2\,dx = \dfrac{x^3}{3}$. **Newton-Leibniz** : $A = \left[\dfrac{x^3}{3}\right]_0^2 = \dfrac{8}{3} - 0 = \dfrac{8}{3} \approx 2{,}67$. **Vérification ordre de grandeur** : sur $[0, 2]$, $x^2$ varie de 0 à 4 ; l''aire moyenne d''un rectangle de hauteur ~2 et largeur 2 serait 4, mais la courbe est concave vers le haut donc l''aire est inférieure. $8/3 \approx 2{,}67$ — cohérent.');

SELECT public._patch_cp_smb('arithmetic_seq', 'Si $u_n = 2n+1$, que vaut $u_3$ ?', 'Pour calculer $u_3$, on remplace $n$ par 3 dans la formule : $u_3 = 2 \times 3 + 1 = 7$. **Attention au piège** : la formule donne directement le terme — pas besoin de calculer $u_0, u_1, u_2$ d''abord pour une formule explicite $u_n = an + b$.');
SELECT public._patch_cp_smb('arithmetic_seq', 'Quelle est la raison de la suite $5, 9, 13, 17$ ?', 'Une suite est arithmétique si la **différence entre termes consécutifs** est constante. Vérification : $9-5 = 4$, $13-9 = 4$, $17-13 = 4$. La raison est $r = 4$. **Piège classique** : confondre le premier terme (5) avec la raison (4) — la raison est l''écart, pas la valeur de départ.');
SELECT public._patch_cp_smb('arithmetic_seq', 'Si $u_0 = 2$ et $r = 3$, que vaut $u_{10}$ ?', 'Terme général d''une suite arithmétique : $u_n = u_0 + n r$. Application : $u_{10} = 2 + 10 \times 3 = 32$. **Attention** : c''est $n r$, pas $(n-1) r$ — la formule part de $u_0$. Si on partait de $u_1$, la formule serait $u_n = u_1 + (n-1) r$.');
SELECT public._patch_cp_smb('arithmetic_seq', 'Somme de $1 + 2 + \dots + 10$ ?', '**Formule de Gauss** : $1 + 2 + \dots + n = \dfrac{n(n+1)}{2}$. Avec $n = 10$ : $S = \dfrac{10 \times 11}{2} = 55$. Forme générale d''une somme arithmétique : (nombre de termes) × (premier + dernier) / 2. Ici : $10 \times (1+10)/2 = 55$ ✓.');
SELECT public._patch_cp_smb('geometric_seq', 'Dans $2, 6, 18, 54$, on multiplie chaque terme par :', 'Suite géométrique : le **rapport entre termes consécutifs** est constant. Calcul : $6/2 = 3$, $18/6 = 3$, $54/18 = 3$. Raison $q = 3$. **Piège** : ne pas confondre raison géométrique (multiplication) et raison arithmétique (addition).');
SELECT public._patch_cp_smb('geometric_seq', 'Quelle est la raison de $8, 4, 2, 1, 0{,}5$ ?', 'Calcul du rapport : $4/8 = 1/2$, $2/4 = 1/2$, etc. Raison $q = 1/2$ — équivalent à diviser par 2. Avec $0 < q < 1$ et $u_0 > 0$, la suite est strictement décroissante vers 0.');
SELECT public._patch_cp_smb('geometric_seq', '$u_0 = 1$, $q = 3$. Que vaut $u_4$ ?', 'Terme général d''une suite géométrique : $u_n = u_0 \cdot q^n$. On part de $u_0 = 1$ et on multiplie par $q = 3$ exactement 4 fois : $u_4 = 1 \cdot 3^4 = 81$. **Vérification** par énumération : $u_0 = 1, u_1 = 3, u_2 = 9, u_3 = 27, u_4 = 81$ ✓.');
SELECT public._patch_cp_smb('geometric_seq', 'Que vaut $1 + 1/2 + 1/4 + \dots$ (somme infinie, $|q|<1$) ?', '**Somme infinie d''une suite géométrique** avec $|q| < 1$ : $S = \dfrac{u_0}{1 - q}$. Ici $u_0 = 1$, $q = 1/2$ : $S = \dfrac{1}{1 - 1/2} = 2$. **Intuition** : chaque terme ajoute la moitié de ce qui restait — paradoxe de Zénon résolu.');
SELECT public._patch_cp_smb('seq_convergence', '$\lim 1/n^2$ vaut :', 'Quand $n \to +\infty$, $n^2 \to +\infty$ encore plus vite. Une fraction « constante / quelque chose qui tend vers $+\infty$ » tend vers 0. **Plus généralement** : pour tout $\alpha > 0$, $\lim 1/n^\alpha = 0$. Pilier des théorèmes de comparaison.');
SELECT public._patch_cp_smb('seq_convergence', '$\lim (0{,}5)^n$ vaut :', 'Suite géométrique de raison $|q| = 0{,}5 < 1$, donc $q^n \to 0$. **Règle générale** : $q^n \to 0$ ssi $|q| < 1$ ; $\to +\infty$ si $q > 1$ ; $= 1$ si $q = 1$ ; pas de limite si $q \le -1$ (oscillations).');
SELECT public._patch_cp_smb('seq_convergence', '$\lim 2^n$ vaut :', 'Suite géométrique de raison $q = 2 > 1$, croissance exponentielle, $\lim 2^n = +\infty$. Comparaison : $2^{10} = 1024$, $2^{20} \approx 10^6$, $2^{30} \approx 10^9$. Cette croissance bat tout polynôme à long terme.');
SELECT public._patch_cp_smb('seq_convergence', 'Le théorème des gendarmes sert à :', '**Théorème des gendarmes** : si $a_n \le u_n \le b_n$ et $\lim a_n = \lim b_n = \ell$, alors $\lim u_n = \ell$. Permet de prouver une convergence par encadrement. Application : encadrer $\sin(n)/n$ par $\pm 1/n \to 0$, donc $u_n \to 0$. Le théorème prouve l''existence de la limite, pas sa valeur (donnée par les gardiens).');
SELECT public._patch_cp_smb('seq_recursive', 'Si $f$ est continue et $u_n \to \ell$, alors :', 'Si $u_{n+1} = f(u_n)$ avec $f$ continue, on passe à la limite : $\ell = f(\ell)$ — équation des points fixes. **Méthode standard** pour trouver les limites d''une suite récurrente. Mais attention : cela suppose que la limite existe — il faut le démontrer séparément (monotonie + bornes).');
SELECT public._patch_cp_smb('seq_recursive', 'Pour conclure à la convergence d''une suite récurrente, on cherche typiquement à montrer qu''elle est :', '**Théorème de la limite monotone** : toute suite monotone et bornée converge. Croissante + majorée → converge ; décroissante + minorée → converge. C''est l''outil principal pour les suites récurrentes en Bac. Sans monotonie ni bornes, on ne peut rien conclure.');
SELECT public._patch_cp_smb('seq_adjacent', 'Si $(u_n)$ croissante, $(v_n)$ décroissante et $v_n - u_n \to 0$, alors :', '**Théorème des suites adjacentes** : convergence vers la même limite. L''intervalle $[u_n, v_n]$ se rétrécit autour d''un point unique. Application classique : encadrement de $\pi$ par périmètres polygonaux. **Condition essentielle** : $v_n - u_n \to 0$ — sans elle, les limites peuvent différer.');
SELECT public._patch_cp_smb('limit_def', '$\lim_{x\to 0} x^2 = ?$', '$x \mapsto x^2$ est polynômiale donc continue partout. Pour une fonction continue, la limite en $a$ vaut $f(a)$. Donc $\lim_{x\to 0} x^2 = 0^2 = 0$. **Toujours essayer la substitution directe avant les techniques avancées** — souvent ça suffit.');
SELECT public._patch_cp_smb('limit_def', '$\lim_{x\to +\infty} \frac{1}{x} = ?$', 'Numérateur fixe, dénominateur $x \to +\infty$. Une fraction « constante / quelque chose qui tend vers $\infty$ » tend vers 0. Cette limite est l''archétype de la décroissance vers 0 à l''infini, fondement des asymptotes horizontales.');
SELECT public._patch_cp_smb('limit_calc', '$\lim_{x\to 4} \frac{x^2-16}{x-4} = ?$', 'Substitution en $x = 4$ : $0/0$, forme indéterminée. Factorise via $a^2 - b^2 = (a-b)(a+b)$ : $x^2 - 16 = (x-4)(x+4)$. La fraction se réduit à $x + 4$ (légitime car $x \ne 4$). Limite : $4 + 4 = 8$. **Pattern** : forme $0/0$ → factorisation cachée.');
SELECT public._patch_cp_smb('limit_calc', '$\lim_{x\to +\infty} \frac{3x+1}{x+5} = ?$', 'Forme $\infty/\infty$. **Astuce** : factoriser $x$ haut et bas. $\dfrac{3x+1}{x+5} = \dfrac{3 + 1/x}{1 + 5/x} \to \dfrac{3}{1} = 3$. **Règle rapide** : pour un quotient de polynômes de même degré à l''infini, la limite est le rapport des coefficients dominants.');
SELECT public._patch_cp_smb('limit_calc', '$\lim_{x\to 0^+} \frac{1}{x} = ?$', 'Limite **à droite** ($x \to 0$ avec $x > 0$). Le dénominateur tend vers 0 par valeurs positives, donc $1/x \to +\infty$. **Attention au signe** : la limite à gauche $\lim_{x\to 0^-} 1/x = -\infty$. La limite globale n''existe pas car les limites latérales diffèrent.');
SELECT public._patch_cp_smb('continuity', 'Une fonction $f$ est continue en $a$ ssi :', 'Définition formelle : **continuité en $a$** ssi $\lim_{x \to a} f(x) = f(a)$. Trois conditions : (1) $f$ définie en $a$, (2) la limite existe, (3) la limite vaut $f(a)$. Géométriquement : on trace la courbe en passant par $a$ sans lever le crayon.');
SELECT public._patch_cp_smb('tvi', 'Le TVI permet de :', '**TVI** garantit l''**existence** d''une solution sans donner sa valeur. Si $f$ continue sur $[a,b]$ et $k$ entre $f(a)$ et $f(b)$, alors $\exists c \in [a,b] : f(c) = k$. Théorème d''existence pure. **Corollaire le plus utilisé** : $f(a) f(b) < 0$ ⇒ $f$ s''annule au moins une fois entre $a$ et $b$.');
SELECT public._patch_cp_smb('tvi', '$f$ continue sur $[0,1]$, $f(0) = 3$, $f(1) = -2$. Le TVI garantit qu''il existe $c$ tel que :', 'Le TVI s''applique aux valeurs **entre** $f(0) = 3$ et $f(1) = -2$, c''est-à-dire dans $[-2, 3]$. **0 est dans cet intervalle**, donc $\exists c \in ]0, 1[ : f(c) = 0$. Les autres valeurs (5, $-3$, 4) sont en dehors — le TVI ne dit rien d''elles.');
SELECT public._patch_cp_smb('deriv_basic', '$f''(a)$ représente géométriquement :', '$f''(a)$ est la **pente de la tangente** à la courbe $y = f(x)$ au point $a$. Mathématiquement : limite du taux d''accroissement $\dfrac{f(a+h) - f(a)}{h}$ quand $h \to 0$. **Interprétation physique** : si $f(t)$ est une position, $f''(t)$ est la vitesse instantanée.');
SELECT public._patch_cp_smb('deriv_basic', '$f(x) = x^2$. Que vaut $f''(3)$ ?', 'Règle des puissances $(x^n)'' = n x^{n-1}$ avec $n = 2$ : $f''(x) = 2x$. En $x = 3$ : $f''(3) = 6$. La tangente au point $(3, 9)$ a pour équation $y = 6(x-3) + 9 = 6x - 9$.');
SELECT public._patch_cp_smb('deriv_basic', '$f(x) = 5x + 1$. Que vaut $f''(2)$ ?', '**Dérivée d''une affine** $f(x) = ax + b$ : $f''(x) = a$ partout (constante). La courbe est une droite, donc tangente = courbe = même pente partout. Pour $f(x) = 5x + 1$ : $f''(2) = 5$. Pas de calcul à faire — la valeur ne dépend pas du point.');
SELECT public._patch_cp_smb('deriv_rules', '$(uv)'' = ?$', '**Règle du produit** : $(uv)'' = u''v + uv''$ — pas $u''v''$ (erreur classique). Démonstration intuitive : la variation du rectangle $u \times v$ vient de la variation de $u$ × $v$, plus celle de $v$ × $u$. Application : $(x e^x)'' = e^x + x e^x = (1+x) e^x$.');
SELECT public._patch_cp_smb('deriv_rules', '$(u/v)'' = ?$', '**Règle du quotient** : $(u/v)'' = \dfrac{u''v - uv''}{v^2}$. **L''ordre dans le numérateur compte** ($u''v - uv''$, pas l''inverse). Dénominateur toujours $v^2$. Application : $(1/x)'' = \dfrac{0 \cdot x - 1 \cdot 1}{x^2} = -1/x^2$ ✓ cohérent avec $(x^{-1})'' = -x^{-2}$.');
SELECT public._patch_cp_smb('deriv_rules', '$(\sin x)'' = ?$', '$(\sin x)'' = \cos x$. **Astuce mnémotechnique** : sin → cos (sans signe), cos → -sin (avec signe). Pente de $\sin$ en 0 = 1 ($= \cos 0$), s''annule en $\pi/2$, devient $-1$ en $\pi$. Cohérent avec la courbe.');
SELECT public._patch_cp_smb('deriv_rules', '$(e^x)'' = ?$', '$(e^x)'' = e^x$ — l''exponentielle est sa propre dérivée. **Propriété caractéristique** : unique solution de $f'' = f$ avec $f(0) = 1$. Explique son omniprésence en physique (désintégration, charge de condensateur, croissance) : partout où la vitesse est proportionnelle à la quantité, on tombe sur l''exponentielle.');
SELECT public._patch_cp_smb('deriv_apps', 'Si $f''(x) > 0$ sur un intervalle, $f$ est :', '**Théorème** : $f$ dérivable et $f'' > 0$ sur $I$ ⇒ $f$ strictement croissante sur $I$. Pente positive = courbe qui monte. Réciproquement $f'' < 0$ ⇒ décroissante, $f'' = 0$ ⇒ constante. C''est l''outil clé pour étudier les variations.');
SELECT public._patch_cp_smb('deriv_apps', 'Un extremum local de $f$ se trouve typiquement où :', '**Théorème de Fermat** : un extremum local d''une fonction dérivable est un point où $f''(x) = 0$ — point critique, tangente horizontale. **Réciproque fausse** : $f''(x) = 0$ n''implique pas un extremum (ex : $x^3$ en 0 — point d''inflexion, pas extremum). Pour confirmer, étudier le signe de $f''$ autour.');
SELECT public._patch_cp_smb('primitives', 'Une primitive de $x^2$ est :', 'Règle : $\int x^n\,dx = \dfrac{x^{n+1}}{n+1} + C$. Avec $n = 2$ : $\int x^2 = \dfrac{x^3}{3} + C$. **Vérification** : $(x^3/3)'' = x^2$ ✓. Toute primitive est définie à une constante près. Pour *une* primitive (pas la), prendre $C = 0$.');
SELECT public._patch_cp_smb('primitives', 'Une primitive de $\cos x$ est :', 'Primitive de $\cos x$ = $\sin x$ (à constante près). **Vérification** : $(\sin x)'' = \cos x$ ✓. **Piège du signe** : la dérivée de $\cos$ est $-\sin$ (avec signe), mais la primitive de $\cos$ est $+\sin$ (sans signe). Le signe n''apparaît que dans la dérivée du cosinus.');
SELECT public._patch_cp_smb('definite_integral', '$\int_a^b f(x) dx$ représente :', '$\int_a^b f$ = **aire signée** entre la courbe $y = f(x)$ et l''axe Ox sur $[a, b]$. Aire positive si $f > 0$ (courbe au-dessus), négative si $f < 0$. **Aire algébrique**, pas l''aire géométrique stricte. Pour la vraie aire, intégrer $|f(x)|$.');
SELECT public._patch_cp_smb('definite_integral', '$\int_a^b f = -\int_b^a f$. Vrai ou faux ?', '**Vrai**. Inverser les bornes change le signe : $\int_a^b f = -\int_b^a f$. Cohérent avec $\int_a^a f = 0$ et la relation de Chasles. Si $\int_a^b f = F(b) - F(a)$, alors $\int_b^a f = F(a) - F(b)$ — signe opposé.');
SELECT public._patch_cp_smb('definite_integral', '$\int_0^2 x\,dx = ?$', 'Primitive de $x$ = $x^2/2$. Newton-Leibniz : $\int_0^2 x\,dx = [x^2/2]_0^2 = 2 - 0 = 2$. **Vérification géométrique** : $y = x$ entre 0 et 2 = triangle rectangle, base 2, hauteur 2, aire = $2 \times 2 / 2 = 2$ ✓.');
SELECT public._patch_cp_smb('integral_apps', 'L''aire entre $y = x^2$ et $y = 0$ sur $[0,1]$ vaut :', 'Aire = $\int_0^1 x^2\,dx = [x^3/3]_0^1 = 1/3$. **Vérification ordre de grandeur** : sur $[0,1]$, $x^2$ varie de 0 à 1, aire ~ 1/3 — cohérent avec $\int_0^1 x^n = 1/(n+1)$.');
SELECT public._patch_cp_smb('integral_apps', 'Une valeur moyenne de $f$ sur $[a,b]$ est :', '**Valeur moyenne** : $\bar{f} = \dfrac{1}{b-a} \int_a^b f$ — hauteur d''un rectangle de largeur $b-a$ ayant même aire que sous la courbe. Si $f(t)$ = vitesse, $\bar{f}$ = vitesse moyenne. **Théorème de la moyenne** : $\exists c \in [a,b] : f(c) = \bar{f}$ (pour $f$ continue).');
SELECT public._patch_cp_smb('prob_basic', 'On lance un dé à 6 faces. Probabilité d''obtenir un 3 ?', 'Dé équilibré : chaque face équiprobable, probabilité $1/6$. **Définition probabilité uniforme** : $P(A) = \dfrac{\text{cas favorables}}{\text{cas possibles}}$. Valable seulement quand toutes les issues sont équiprobables (dé non truqué).');
SELECT public._patch_cp_smb('prob_basic', 'Si $P(A) = 0{,}3$, alors $P(\bar{A}) = ?$', '$P(A) + P(\bar{A}) = 1$ (l''un ou l''autre se produit toujours). Donc $P(\bar{A}) = 1 - 0{,}3 = 0{,}7$. **Astuce** : passer au complémentaire est souvent plus simple — pour « au moins un », calculer « aucun » et soustraire.');
SELECT public._patch_cp_smb('prob_basic', '$P(A \cup B) = ?$ (général)', '**Inclusion-exclusion** : $P(A \cup B) = P(A) + P(B) - P(A \cap B)$. On retire $P(A \cap B)$ pour ne pas compter deux fois les issues communes. **Cas particulier** : si $A, B$ incompatibles ($A \cap B = \emptyset$), $P(A \cup B) = P(A) + P(B)$. Erreur classique : oublier le terme négatif et obtenir $P > 1$.');
SELECT public._patch_cp_smb('conditional_prob', '$P(A | B) = ?$', '**Probabilité conditionnelle** : $P(A|B) = \dfrac{P(A \cap B)}{P(B)}$ (pour $P(B) > 0$). On se restreint à l''univers où $B$ s''est réalisé. **Réécriture** : $P(A \cap B) = P(B) \cdot P(A|B)$ — utile pour les arbres pondérés.');
SELECT public._patch_cp_smb('conditional_prob', '$A$ et $B$ sont indépendants ssi :', '$A, B$ **indépendants** ⇔ $P(A \cap B) = P(A) \cdot P(B)$, ou équivalent $P(A|B) = P(A)$. **Indépendance ≠ incompatibilité** : indépendant = sans influence ; incompatible = ne peuvent coexister. Deux notions distinctes.');
SELECT public._patch_cp_smb('random_variables', 'L''espérance $E(X)$ représente :', '**Espérance** = valeur moyenne sur un grand nombre d''expériences. Pour discrète : $E(X) = \sum x_i P(X = x_i)$. Si on parie sur $X$, $E(X)$ est l''espéré gain. **Exemple** : dé 6 faces, $E = (1+2+3+4+5+6)/6 = 3{,}5$.');
SELECT public._patch_cp_smb('random_variables', '$V(X) = ?$ en fonction de $E(X)$', '**Variance** = mesure de dispersion. Formule de König : $V(X) = E(X^2) - (E(X))^2$. Plus pratique en pratique que $E((X - E(X))^2)$. **Écart-type** $\sigma = \sqrt{V}$ a les mêmes unités que $X$. $V = 0$ ⇔ $X$ constante.');
SELECT public._patch_cp_smb('complex_basics', '$i^2 = ?$', 'Définition : $i^2 = -1$. C''est ce qui distingue $\mathbb{C}$ de $\mathbb{R}$. **Conséquences** : $i^3 = -i$, $i^4 = 1$, cycle de période 4 : $1, i, -1, -i, 1, \dots$. Très utile pour simplifier $i^n$ quand $n$ est grand.');
SELECT public._patch_cp_smb('complex_basics', '$|3 + 4i| = ?$', '**Module** : $|a + bi| = \sqrt{a^2 + b^2}$ = distance à l''origine. Pour $3 + 4i$ : $|z| = \sqrt{9 + 16} = \sqrt{25} = 5$. **Astuce** : reconnaître le triplet pythagoricien $(3, 4, 5)$ — courant dans les exercices.');
SELECT public._patch_cp_smb('complex_basics', 'Conjugué de $2 - 3i$ ?', '**Conjugué** : $\overline{a + bi} = a - bi$ (signe imaginaire changé). $\overline{2 - 3i} = 2 + 3i$. **Propriétés** : $z \bar{z} = a^2 + b^2 = |z|^2$ (réel positif) ; $\overline{\bar{z}} = z$. Sert à simplifier $1/(a+bi)$ par multiplication par le conjugué.');
SELECT public._patch_cp_smb('complex_trig', 'Forme trigonométrique de $1 + i$ ?', 'Module : $|1+i| = \sqrt{2}$. Argument : $\tan\theta = 1$, $z$ en quadrant 1, donc $\theta = \pi/4$. Forme : $1 + i = \sqrt{2}(\cos(\pi/4) + i\sin(\pi/4)) = \sqrt{2} e^{i\pi/4}$.');
SELECT public._patch_cp_smb('complex_trig', 'Avec $z = re^{i\theta}$, $z^n = ?$', '**Formule de Moivre** : $z^n = r^n e^{in\theta}$. Multiplier les modules, additionner les arguments. **Application typique** : $(1+i)^4 = (\sqrt{2})^4 e^{i\pi} = 4 \times (-1) = -4$ — calcul instantané vs développement laborieux.');
SELECT public._patch_cp_smb('complex_geometry', 'Le module $|z_B - z_A|$ représente :', '$|z_B - z_A|$ = **distance** entre les points $A, B$ d''affixes $z_A, z_B$. C''est le module appliqué au vecteur $\vec{AB}$ d''affixe $z_B - z_A$. **Application** : alignement, équidistance, identification de triangles particuliers — calculer des modules.');
SELECT public._patch_cp_smb('complex_geometry', '$\arg(z_B - z_A)$ représente :', '$\arg(z_B - z_A)$ = **angle** du vecteur $\vec{AB}$ avec l''axe Ox, sens trigonométrique. Avec le module, donne les coordonnées polaires de $\vec{AB}$. **Application** : identifier triangles équilatéraux, rectangles, etc.');
SELECT public._patch_cp_smb('ode_first_order', 'Solution générale de $y'' = ky$ ?', '$y'' = ky$ → solution générale $y(x) = C e^{kx}$, $C \in \mathbb{R}$. Naturellement exponentielle : la dérivée proportionnelle à la fonction caractérise $\exp$. $C$ déterminée par condition initiale. Modélise désintégration ($k<0$), croissance ($k>0$).');
SELECT public._patch_cp_smb('ode_first_order', 'Solution de $y'' + 2y = 0$, $y(0) = 5$ ?', '$y'' + 2y = 0 \iff y'' = -2y$. Solution générale : $y = C e^{-2x}$. Condition $y(0) = C = 5$. Donc $y(x) = 5 e^{-2x}$. **Vérification** : $y'' = -10 e^{-2x} = -2y$ ✓.');
SELECT public._patch_cp_smb('ode_second_order', '$y'''' + \omega^2 y = 0$ a pour solutions :', '**Oscillateur harmonique** : $y(x) = A\cos(\omega x) + B\sin(\omega x)$. **Vérification** : $(\cos\omega x)'''' = -\omega^2 \cos\omega x$ ✓. Modélise pendule (petites oscillations), ressort idéal, circuit LC. Pulsation $\omega$ → période $T = 2\pi/\omega$.');
SELECT public._patch_cp_smb('kinematics', 'L''accélération est la dérivée de :', '**Accélération** $a(t) = dv/dt$ = dérivée de la vitesse. Aussi : dérivée seconde de la position, $a = d^2x/dt^2$. Mémo : position $\to$ vitesse $\to$ accélération (dériver). Inversement : intégrer $a$ → $v$ → $x$.');
SELECT public._patch_cp_smb('kinematics', 'En MRUA, $v(t) = ?$', '**MRUA** = Mouvement Rectiligne Uniformément Accéléré, $a$ = constante. Par intégration : $v(t) = v_0 + at$. Position : $x(t) = x_0 + v_0 t + \dfrac{1}{2} a t^2$. Application : chute libre ($g \approx 9{,}8$ m/s², la vitesse augmente d''environ 10 m/s par seconde).');
SELECT public._patch_cp_smb('newtons_laws', '$\sum \vec{F} = ?$ (2ème loi de Newton)', '**2ème loi de Newton** : $\sum \vec{F} = m \vec{a}$. Somme vectorielle des forces = masse × accélération. Équation fondamentale de la dynamique. Si $\sum \vec{F} = \vec{0}$ → équilibre dynamique ($\vec{a} = 0$, MRU) ; si une force unique $F$ → $a = F/m$.');
SELECT public._patch_cp_smb('newtons_laws', 'Principe d''inertie (1ère loi) :', '**1ère loi (inertie)** : $\sum \vec{F} = \vec{0}$ → mouvement rectiligne uniforme ou repos. Tout changement de vitesse ⇒ force non nulle. **Conséquence** : pas besoin de force pour maintenir un mouvement, c''est l''inertie qui le fait — révolution conceptuelle d''Aristote à Newton.');
SELECT public._patch_cp_smb('energy', 'Énergie cinétique $E_c = ?$', '$E_c = \dfrac{1}{2} m v^2$ — proportionnelle à $v^2$ (pas $v$ !). Doubler la vitesse quadruple $E_c$. Unité : J (joule). **Application** : véhicule à 100 km/h a 4× l''énergie d''un à 50 km/h — d''où la croissance rapide de la distance de freinage.');
SELECT public._patch_cp_smb('energy', 'Théorème de l''énergie cinétique :', '$\Delta E_c = W_{\text{forces}}$ — variation d''énergie cinétique = somme des travaux des forces. Convertit un problème dynamique en un problème énergétique scalaire (plus simple). **Application** : calculer la vitesse en bas d''un toboggan sans résoudre l''équation de mouvement.');
SELECT public._patch_cp_smb('wave_properties', '$v = \lambda f$ relie :', '**Relation fondamentale des ondes** : vitesse = longueur d''onde × fréquence. Universelle (mécaniques, électromagnétiques, matière). Pour la lumière dans le vide : $v = c \approx 3 \times 10^8$ m/s. Une couleur de $\lambda = 500$ nm a $f = c/\lambda = 6 \times 10^{14}$ Hz.');
SELECT public._patch_cp_smb('sound_light', 'La diffraction est observable quand :', '**Diffraction** observable quand l''ouverture/obstacle a une dimension de l''ordre de $\lambda$. Critère : $a \lesssim \lambda$ → diffraction nette. **Exemple** : on entend le son derrière un mur ($\lambda \sim 1$ m) mais on ne voit pas ($\lambda \sim 500$ nm, beaucoup plus petit que le mur).');
SELECT public._patch_cp_smb('rc_rl_circuits', 'Constante de temps d''un circuit RC : $\tau = ?$', '$\tau = RC$ (s, avec R en Ω, C en F). À $t = \tau$, condensateur chargé à 63% ($1 - e^{-1}$) ; à $5\tau$, plus de 99% — régime établi. **Mémo** : $\tau$ grand = lent, $\tau$ petit = rapide. Pour RL : $\tau = L/R$.');
SELECT public._patch_cp_smb('rlc_oscillations', 'Pulsation propre LC : $\omega_0 = ?$', '$\omega_0 = \dfrac{1}{\sqrt{LC}}$. Période $T_0 = 2\pi\sqrt{LC}$. **Analogie mécanique** : $L$ = masse (inertie), $C$ = inverse de la raideur. LC = oscillateur harmonique électrique. Avec résistance, oscillations amorties.');
SELECT public._patch_cp_smb('acid_base', '$pH = -\log_{10}([H_3O^+])$. Si $[H_3O^+] = 10^{-3}$ mol/L, $pH = ?$', '$pH = -\log_{10}(10^{-3}) = 3$. **Mémo** : pH = exposant changé de signe. Acide ($pH < 7$) : forte $[H_3O^+]$. Basique ($pH > 7$) : faible. **Échelle log** : $\Delta pH = 1$ ⇔ facteur 10 sur $[H_3O^+]$.');
SELECT public._patch_cp_smb('acid_base', 'Une solution avec $pH = 13$ est :', '$pH = 13 > 7$ : **fortement basique** (proche de 14, la limite haute). $[H_3O^+] = 10^{-13}$ mol/L. Exemples : soude concentrée, lessive. À l''inverse : $pH \le 1$ = fortement acide. $pH = 7$ = neutre.');
SELECT public._patch_cp_smb('redox', 'Une oxydation est :', '**Oxydation** = perte d''électrons. Notation : $Red \to Ox + ne^-$. **Mémo OIL RIG** : Oxidation Is Loss, Reduction Is Gain. Exemple : $Zn \to Zn^{2+} + 2e^-$. Réduction = gain. Les deux simultanément dans une réaction redox.');
SELECT public._patch_cp_smb('redox', 'Dans une pile, l''anode est le siège de :', 'À l''**anode** (pôle **négatif** d''une pile) : **oxydation**. L''espèce y perd des électrons qui partent dans le circuit. **Mémo** : Anode → ox**A**ydation ; **C**athode → ré**du**ction. À la cathode (pôle +), arrivée des électrons et réduction.');

DROP FUNCTION public._patch_cp_smb(TEXT, TEXT, TEXT);
DROP FUNCTION public._patch_tryit_smb(TEXT, TEXT, TEXT, TEXT);

COMMIT;
